(() => {
  const data = window.RADAR, app = document.querySelector('#app');
  if (!data) { app.textContent = 'Run main.ts to generate the offline dataset.'; return; }
  const state = { query:'', filter:'all', selected:null, sort:'rank' };
  const money = n => n == null ? '—' : n >= 1e9 ? '$'+(n/1e9).toFixed(2)+'B' : n >= 1e6 ? '$'+(n/1e6).toFixed(1)+'M' : '$'+Math.round(n/1000)+'K';
  const pct = n => n == null ? '—' : (n>0?'+':'')+n.toFixed(1)+'%';
  const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const risk = r => r.change_7d == null ? 'DATA GAP' : r.change_7d < -10 ? 'TVL DECLINE' : r.age_days == null ? 'AGE UNKNOWN' : 'MONITOR';
  function render() {
    let rows = data.rows.filter(r => (r.name+' '+r.slug+' '+r.chains.join(' ')+' '+r.category).toLowerCase().includes(state.query.toLowerCase()));
    if (state.filter==='solana') rows=rows.filter(r=>r.chains.includes('Solana'));
    if (state.filter==='early') rows=rows.filter(r=>r.tvl_usd<data.floor_usd);
    if (state.filter==='risk') rows=rows.filter(r=>risk(r)!=='MONITOR');
    if (state.sort==='tvl') rows.sort((a,b)=>b.tvl_usd-a.tvl_usd);
    if (state.sort==='growth') rows.sort((a,b)=>(b.change_7d??-Infinity)-(a.change_7d??-Infinity));
    const top=data.rows[0], selected=data.rows.find(r=>r.slug===state.selected);
    app.innerHTML=`<header><div class="brand"><span class="mark">✳</span><div><b>SIGNAL<span> / </span>DESK</b><small>PROTOCOL INTELLIGENCE</small></div></div><nav><a href="#ranking">RANKINGS</a><a href="#method">METHODOLOGY</a><a href="#sources">SOURCES</a></nav><div class="status"><i></i> SEALED SNAPSHOT <strong>${esc(data.as_of)}</strong></div></header>
    <main><section class="intro"><div><div class="eyebrow"><span>01 / MARKET INTELLIGENCE</span> <span>RESEARCH NOTE • ${esc(data.as_of)}</span></div><h1>Find the signal<br><em>before the token.</em></h1><p>A research terminal for protocols with no token recorded in the snapshot. A modelled value, not a launch prediction.</p><div class="intro-foot"><span><b>${data.board_size}</b> protocols ranked</span><span><b>${data.watchlist_size}/${data.watchlist_size}</b> watchlist covered</span><span><b>${data.early_size}</b> below the floor</span></div></div><aside class="lead"><div class="lead-top">HIGHEST IMPLIED VALUE <span>↗ 01</span></div><h2>${esc(top.name)}</h2><div class="lead-value">${money(top.implied_value_usd)}</div><div class="lead-meta"><span>TVL <b>${money(top.tvl_usd)}</b></span><span>7D CHANGE <b>${pct(top.change_7d)}</b></span></div><div class="lead-bottom">MODEL ESTIMATE <span>NOT A MARKET PRICE</span></div></aside></section>
    <section class="strip"><div><span>THE UNIVERSE</span><b>${data.board_size} <small>ranked protocols</small></b></div><div><span>SCREEN</span><b>${money(data.floor_usd)} <small>watchlist TVL floor</small></b></div><div><span>MODEL</span><b>0.30× <small>TVL starting multiple</small></b></div><div><span>IMPORTANT</span><b>No token recorded <small>≠ no token exists</small></b></div></section>
    <section id="ranking" class="workspace"><div class="section-head"><div><div class="eyebrow">02 / THE RADAR</div><h2>Opportunity board<span>.</span></h2><p>Ranked by modelled implied value. Select a protocol to inspect the assumptions and farm plan.</p></div><div class="count">${rows.length} <small>RESULTS</small></div></div><div class="controls"><div class="tabs">${[['all','All protocols'],['solana','Solana'],['early','Below floor'],['risk','Risk signals']].map(([v,l])=>`<button data-filter="${v}" class="${state.filter===v?'active':''}">${l}</button>`).join('')}</div><div class="inputs"><input id="search" aria-label="Search protocols" placeholder="Search name, chain..." value="${esc(state.query)}"><select id="sort" aria-label="Sort"><option value="rank">Sort: implied value</option><option value="tvl" ${state.sort==='tvl'?'selected':''}>Sort: TVL</option><option value="growth" ${state.sort==='growth'?'selected':''}>Sort: 7d change</option></select></div></div>
    <div class="tablewrap"><table><thead><tr><th>RANK</th><th>PROTOCOL / CATEGORY</th><th>NETWORK</th><th>TVL</th><th>7D CHANGE</th><th>IMPLIED VALUE</th><th>SIGNAL</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr data-slug="${esc(r.slug)}" tabindex="0"><td class="rank">${String(r.rank).padStart(2,'0')}</td><td><strong>${esc(r.name)}</strong><small>${esc(r.category||'Unclassified')}</small></td><td>${esc(r.chains.slice(0,2).join(' / ')||'—')}</td><td>${money(r.tvl_usd)}</td><td class="${r.change_7d<0?'negative':'positive'}">${pct(r.change_7d)}</td><td class="value">${money(r.implied_value_usd)}</td><td><span class="pill ${risk(r)==='MONITOR'?'':'warn'}">${risk(r)}</span></td><td>↗</td></tr>`).join('')}</tbody></table>${rows.length?'':'<p class="empty">No matching protocols. Try a different search.</p>'}</div></section>
    <section id="method" class="notes"><div><div class="eyebrow">03 / HOW TO READ THIS</div><h2>Model, not<br><em>market price.</em></h2><p>One consistent framework applied to the sealed data. The number is a relative research signal, not a forecast or valuation of a tradable asset.</p></div><div class="method-card"><span>THE FORMULA</span><h3>TVL × 0.30 × growth × maturity</h3><p>Growth = 1 + 0.35 × seven-day change, clamped to −60% / +120%. Maturity rises from 0.6 to 1 over three years of tracking. Unknown age uses 365 days; missing growth uses zero.</p><div class="rule"></div><p>Tracking age is not proof of time without a token. TVL may include deposits that are not revenue. A token, airdrop, eligibility or return is never guaranteed.</p></div><div id="sources" class="method-card"><span>PROVENANCE / LIMITATIONS</span><h3>One fixed view.</h3><p>${esc(data.source)}</p><p>Watchlist: all ${data.watchlist_size} snapshot entries; ${data.early_size} additional candidates below the floor. Existing-token records appear separately in the live-token view below.</p><p>Verify contract addresses, current terms, liquidity and eligibility independently before acting. Gas and capital estimates are illustrative.</p></div></section><section class="live"><div class="eyebrow">04 / SEPARATE UNIVERSE</div><h2>Recorded live tokens <span>${data.live_size} TRACKED</span></h2><p>Market caps from the snapshot; excluded from the implied-value ranking.</p><div>${data.live.slice(0,8).map(r=>`<span>${esc(r.name)} <b>${money(r.mcap_usd)}</b></span>`).join('')}</div></section><footer>SIGNAL / DESK <span>OFFLINE RESEARCH • ${esc(data.as_of)} • NOT INVESTMENT ADVICE</span></footer></main>${selected?detail(selected):''}`;
    document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{state.filter=b.dataset.filter;render()});
    document.querySelectorAll('[data-slug]').forEach(tr=>{tr.onclick=()=>{state.selected=tr.dataset.slug;render()};tr.onkeydown=e=>{if(e.key==='Enter')tr.click()}});
    const search=document.querySelector('#search'); search.oninput=e=>{const pos=e.target.selectionStart;state.query=e.target.value;render();const el=document.querySelector('#search');el.focus();el.setSelectionRange(pos,pos)};
    document.querySelector('#sort').onchange=e=>{state.sort=e.target.value;render()};
    if(selected) document.querySelector('#close').onclick=()=>{state.selected=null;render()};
  }
  function detail(r) { return `<div class="overlay"><aside class="drawer"><button id="close" aria-label="Close detail">×</button><div class="eyebrow">PROTOCOL BRIEF / ${String(r.rank).padStart(2,'0')}</div><h2>${esc(r.name)}<span>.</span></h2><p>${esc(r.category||'Unclassified')} · ${esc(r.chains.join(' / ')||'Chain unspecified')}</p><div class="detail-value"><small>MODELLED IMPLIED VALUE</small><b>${money(r.implied_value_usd)}</b><span>NOT A TRADING PRICE</span></div><div class="detail-grid"><div>TVL <b>${money(r.tvl_usd)}</b></div><div>7D CHANGE <b>${pct(r.change_7d)}</b></div><div>TRACKED <b>${r.age_days==null?'Unknown':r.age_days+' days'}</b></div><div>RISK SIGNAL <b>${risk(r)}</b></div></div><h3>Value bridge <span>01</span></h3><p>${money(r.tvl_usd)} TVL × 0.30 × ${r.growth_multiplier.toFixed(2)} growth × ${r.maturity_multiplier.toFixed(2)} maturity. Rounded to the nearest dollar in the board.</p><h3>Farm plan <span>02</span></h3><p>Illustrative actions, not verified eligibility. Confirm the app and asset before committing capital.</p><ol>${r.farm_steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><div class="warning">⚑ Contract, liquidity and capital loss risks apply. No airdrop is promised.</div></aside></div>`; }
  render();
})();
